WITH valid_products AS (SELECT *, COALESCE(price, 0) AS price_filled FROM products WHERE supplier_id IN (13, 24, 29) AND launch_date <= '2024-12-28'), products_stats AS (SELECT brand, MIN(launch_date) AS min_launch_date, COUNT(CASE WHEN category = 'Books' THEN 1 END) AS books_count FROM valid_products GROUP BY brand) SELECT brand, books_count FROM products_stats ORDER BY 1 LIMIT 3
